//! Picks the eligible member with the lowest declared input price. This is the
//! worked example of `.claude/skills/port-router-to-rust`: its Python input is
//! `example/cheapest_first.py`, and `testdata/pick-table.json` is generated by
//! running that Python policy.
//!
//! A strategy sees its own params, the member list and per-candidate state, not
//! the model catalog: the Python policy's price table therefore becomes
//! `MemberParams`, one entry per router member. Built into a gateway with
//! the router plugin directory as a WASM component.

#[cfg(test)]
use lumewarp_plugin_sdk as lumewarp_router_api;
use lumewarp_plugin_sdk::{
    Candidates, ConfigError, Configure, Needs, RequestInfo, RngCore, RouterInfo, Strategy,
};
use schemars::JsonSchema;
use serde::Deserialize;

#[derive(Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Params {
    /// Never pick a member priced above this, in nano-USD per million input tokens.
    /// Unpriced members are excluded while it is set: the cap cannot be checked
    /// against an unknown price.
    #[schemars(title = "Max input price (nano-USD per Mtok)", range(min = 1))]
    pub max_input_price_nano_usd_per_mtok: Option<u64>,
}

#[derive(Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct MemberParams {
    /// Input price in nano-USD per million tokens. Leave it out when the price
    /// is unknown; 0 means free.
    #[schemars(title = "Input price (nano-USD per Mtok)")]
    pub input_price_nano_usd_per_mtok: Option<u64>,
}

pub struct CheapestFirst {
    /// By `Candidate::member_index`: stable across traffic-split pools.
    /// `None` is an unpriced member.
    prices: Box<[Option<u64>]>,
    max_price: Option<u64>,
}

impl Configure<Params, MemberParams> for CheapestFirst {
    fn configure(
        _: &RouterInfo<'_>,
        params: Params,
        members: &[MemberParams],
    ) -> Result<Self, ConfigError> {
        // The annotation creates no runtime check: standalone YAML and snapshots
        // reach this without passing the schema.
        if params.max_input_price_nano_usd_per_mtok == Some(0) {
            return Err(ConfigError(
                "max_input_price_nano_usd_per_mtok must be at least 1".into(),
            ));
        }
        Ok(Self {
            prices: members
                .iter()
                .map(|m| m.input_price_nano_usd_per_mtok)
                .collect(),
            max_price: params.max_input_price_nano_usd_per_mtok,
        })
    }
}

impl Strategy for CheapestFirst {
    fn pick(
        &self,
        _: &RequestInfo<'_>,
        candidates: &Candidates<'_>,
        _: &mut dyn RngCore,
    ) -> Option<usize> {
        candidates
            .iter()
            .filter(|c| match (self.max_price, self.prices[c.member_index()]) {
                (Some(max), Some(price)) => price <= max,
                (Some(_), None) => false,
                (None, _) => true,
            })
            // Priced before unpriced, then price, load, and member order: a
            // tuple on the stack, no allocation. The last key makes the result
            // independent of the pool's order (traffic splits reorder members).
            .min_by_key(|c| {
                let price = self.prices[c.member_index()];
                (
                    price.is_none(),
                    price.unwrap_or(0),
                    c.in_flight(),
                    c.member_index(),
                )
            })
            .map(|c| c.index)
    }
}

lumewarp_plugin_sdk::register! {
    kind: "router-strategy",
    name: "cheapest_first",
    title: "Cheapest first",
    description: "Use the eligible member with the lowest input price; unpriced members come last.",
    uses_weight: false,
    needs: Needs::default(),
    params: Params,
    member_params: MemberParams,
    strategy: CheapestFirst,
}

#[cfg(test)]
mod tests {
    use super::*;
    use lumewarp_router_api::{lookup, CandidateSource, Load, MemberInfo, ThreadRng};
    use serde_json::{json, Value};

    /// A pool with explicit member indices: a traffic split hands a pool only a
    /// subset of the router's members, in its own order.
    struct Pool<'a> {
        names: &'a [&'a str],
        members: &'a [usize],
        in_flight: &'a [usize],
    }

    impl CandidateSource for Pool<'_> {
        fn len(&self) -> usize {
            self.names.len()
        }
        fn name(&self, i: usize) -> &str {
            self.names[i]
        }
        fn member_index(&self, i: usize) -> usize {
            self.members[i]
        }
        fn weight(&self, _: usize) -> u64 {
            1
        }
        fn in_flight(&self, i: usize) -> usize {
            self.in_flight[i]
        }
        fn latency_ewma_us(&self, _: usize) -> Option<u64> {
            None
        }
        fn load(&self, _: usize) -> Load {
            Load {
                waiting: 0,
                kv_usage_bp: 0,
                fresh: false,
            }
        }
        fn total_weight(&self) -> u64 {
            self.names.len() as u64
        }
        fn weighted_index(&self, draw: u64) -> usize {
            draw as usize
        }
    }

    fn create(params: Value, member_params: &[Value]) -> Result<Box<dyn Strategy>, ConfigError> {
        let names: Vec<String> = (0..member_params.len()).map(|i| format!("m{i}")).collect();
        let infos: Vec<MemberInfo<'_>> = names
            .iter()
            .map(|model| MemberInfo {
                model: model.as_str(),
                weight: 1,
                split: None,
            })
            .collect();
        let info = RouterInfo {
            name: "r",
            members: &infos,
        };
        let factory = lookup("cheapest_first")
            .expect("registered")
            .expect("exactly one registration");
        (factory.create)(&info, &params, member_params)
    }

    fn pick(strategy: &dyn Strategy, pool: &Pool<'_>, offered: &[bool]) -> Option<usize> {
        let request = RequestInfo::new("r", "", "", None, &[], &|_| None);
        let eligible = |i: usize| offered[i];
        strategy.pick(
            &request,
            &Candidates::new(
                pool as &dyn CandidateSource,
                &eligible as &dyn Fn(usize) -> bool,
            ),
            &mut ThreadRng,
        )
    }

    fn offered(len: usize) -> Vec<bool> {
        vec![true; len]
    }

    /// One row per scenario, with the expected winner computed by the Python
    /// policy. Regenerate with the command in `testdata/README.md`.
    #[test]
    fn pick_matches_the_python_policy() {
        let table: Value =
            serde_json::from_str(include_str!("../testdata/pick-table.json")).unwrap();
        let cases = table["cases"].as_array().unwrap();
        assert!(cases.len() >= 10);
        assert!(cases.iter().any(|c| c["pick"].is_null()));
        assert!(cases.iter().any(|c| !c["pick"].is_null()));
        for case in cases {
            let members = case["members"].as_array().unwrap();
            let member_params: Vec<Value> = members.iter().map(|m| m["params"].clone()).collect();
            let strategy = create(case["params"].clone(), &member_params)
                .unwrap_or_else(|e| panic!("{}: {e}", case["name"]));
            let names: Vec<&str> = members
                .iter()
                .map(|m| m["model"].as_str().unwrap())
                .collect();
            let members_index: Vec<usize> = (0..names.len()).collect();
            let in_flight: Vec<usize> = case["in_flight"]
                .as_array()
                .unwrap()
                .iter()
                .map(|n| n.as_u64().unwrap() as usize)
                .collect();
            let eligible: Vec<bool> = case["eligible"]
                .as_array()
                .unwrap()
                .iter()
                .map(|ok| ok.as_bool().unwrap())
                .collect();
            let pool = Pool {
                names: &names,
                members: &members_index,
                in_flight: &in_flight,
            };
            let picked = pick(&*strategy, &pool, &eligible);
            assert_eq!(
                picked.map(|i| pool.name(i)),
                case["pick"].as_str(),
                "{}",
                case["name"]
            );
        }
    }

    #[test]
    fn an_unpriced_member_is_a_last_resort() {
        let strategy = create(
            json!({}),
            &[json!({}), json!({"input_price_nano_usd_per_mtok": 100})],
        )
        .unwrap();
        let pool = Pool {
            names: &["unpriced", "priced"],
            members: &[0, 1],
            in_flight: &[0, 20],
        };
        assert_eq!(
            pick(&*strategy, &pool, &offered(2)),
            Some(1),
            "a busier priced member still beats an idle unpriced one"
        );
        assert_eq!(
            pick(&*strategy, &pool, &[true, false]),
            Some(0),
            "unpriced is used when no priced member is eligible"
        );
    }

    const SPLIT_MEMBERS: [MemberInfo<'static>; 3] = [
        MemberInfo {
            model: "a",
            weight: 1,
            split: Some("x"),
        },
        MemberInfo {
            model: "b",
            weight: 1,
            split: Some("x"),
        },
        MemberInfo {
            model: "a",
            weight: 1,
            split: Some("y"),
        },
    ];

    fn split_strategy(a: u64, b: u64, a_other_split: u64) -> Box<dyn Strategy> {
        let factory = lookup("cheapest_first").unwrap().unwrap();
        let info = RouterInfo {
            name: "r",
            members: &SPLIT_MEMBERS,
        };
        let members = [
            json!({"input_price_nano_usd_per_mtok": a}),
            json!({"input_price_nano_usd_per_mtok": b}),
            json!({"input_price_nano_usd_per_mtok": a_other_split}),
        ];
        (factory.create)(&info, &json!({}), &members).unwrap()
    }

    #[test]
    fn a_model_listed_in_two_splits_has_its_own_price() {
        // "a" is 100 in split x and 50 in split y; "b" is 300 in split x.
        let strategy = split_strategy(100, 300, 50);
        let only_y = Pool {
            names: &["a"],
            members: &[2],
            in_flight: &[0],
        };
        assert_eq!(pick(&*strategy, &only_y, &offered(1)), Some(0));
        // Both entries of "a" in one pool: the cheaper split (member 2) wins,
        // and it is pool index 1, so `Candidate.index` alone would be wrong.
        let both = Pool {
            names: &["a", "a"],
            members: &[0, 2],
            in_flight: &[0, 0],
        };
        assert_eq!(pick(&*strategy, &both, &offered(2)), Some(1));
    }

    #[test]
    fn a_full_tie_follows_member_order_whatever_the_pool_order_is() {
        let strategy = split_strategy(100, 100, 100);
        let in_order = Pool {
            names: &["a", "a"],
            members: &[0, 2],
            in_flight: &[0, 0],
        };
        let reversed = Pool {
            names: &["a", "a"],
            members: &[2, 0],
            in_flight: &[0, 0],
        };
        assert_eq!(pick(&*strategy, &in_order, &offered(2)), Some(0));
        assert_eq!(pick(&*strategy, &reversed, &offered(2)), Some(1));
    }

    #[test]
    fn configure_is_strict_about_the_declared_settings() {
        let ok = |params: Value, member: Value| create(params, &[member]).is_ok();
        assert!(ok(json!({}), json!({})), "both settings are optional");
        assert!(ok(json!({}), json!({"input_price_nano_usd_per_mtok": 0})));
        assert!(ok(
            json!({"max_input_price_nano_usd_per_mtok": 1}),
            json!({"input_price_nano_usd_per_mtok": u64::MAX})
        ));
        // The schema says minimum 1; serde does not, so configure must.
        assert!(!ok(
            json!({"max_input_price_nano_usd_per_mtok": 0}),
            json!({})
        ));
        assert!(!ok(json!({"other": 1}), json!({})));
        assert!(!ok(
            json!({"max_input_price_nano_usd_per_mtok": "1"}),
            json!({})
        ));
        assert!(!ok(
            json!({"max_input_price_nano_usd_per_mtok": -1}),
            json!({})
        ));
        assert!(!ok(json!({}), json!({"other": 1})));
        assert!(!ok(
            json!({}),
            json!({"input_price_nano_usd_per_mtok": "100"})
        ));
        assert!(!ok(json!({}), json!({"input_price_nano_usd_per_mtok": -1})));
        assert!(!ok(
            json!({}),
            json!({"input_price_nano_usd_per_mtok": 1.5})
        ));
    }

    #[test]
    fn the_descriptor_comes_from_the_structs() {
        let descriptor = lumewarp_router_api::descriptors()
            .into_iter()
            .find(|d| d.name == "cheapest_first")
            .unwrap();
        assert!(!descriptor.uses_weight);
        assert!(descriptor.needs.is_empty());
        assert_eq!(
            descriptor.member_schema["properties"]["input_price_nano_usd_per_mtok"]["title"],
            json!("Input price (nano-USD per Mtok)")
        );
        assert_eq!(
            descriptor.params_schema["properties"]["max_input_price_nano_usd_per_mtok"]["minimum"],
            json!(1)
        );
        assert_eq!(descriptor.digest.len(), 64);
    }

    /// `pick` runs on the request path: what it does must not allocate. The
    /// gateway's own path test covers the vtable; this covers the strategy.
    #[test]
    fn pick_allocates_nothing() {
        let strategy = create(
            json!({}),
            &[json!({"input_price_nano_usd_per_mtok": 100}), json!({})],
        )
        .unwrap();
        let pool = Pool {
            names: &["a", "b"],
            members: &[0, 1],
            in_flight: &[0, 1],
        };
        let offered = offered(2);
        assert_eq!(pick(&*strategy, &pool, &offered), Some(0));
        let (allocations, picked) = allocation::count(|| pick(&*strategy, &pool, &offered));
        assert_eq!(picked, Some(0));
        assert_eq!(allocations, 0);
    }

    #[cfg(test)]
    mod allocation {
        use std::alloc::{GlobalAlloc, Layout, System};
        use std::cell::Cell;

        thread_local! {
            static COUNT: Cell<usize> = const { Cell::new(0) };
        }

        struct Counting;

        fn bump() {
            let _ = COUNT.try_with(|count| count.set(count.get() + 1));
        }

        unsafe impl GlobalAlloc for Counting {
            unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
                bump();
                unsafe { System.alloc(layout) }
            }
            unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
                bump();
                unsafe { System.alloc_zeroed(layout) }
            }
            unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
                bump();
                unsafe { System.realloc(ptr, layout, new_size) }
            }
            unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
                unsafe { System.dealloc(ptr, layout) }
            }
        }

        #[global_allocator]
        static GLOBAL: Counting = Counting;

        /// Allocations made on this thread while running `f`.
        pub fn count<T>(f: impl FnOnce() -> T) -> (usize, T) {
            let before = COUNT.with(Cell::get);
            let value = f();
            let after = COUNT.with(Cell::get);
            (after - before, value)
        }
    }
}
